create or replace function public.allocate_supplier_purchase(p_company_id uuid,p_purchase_id uuid,p_allocations jsonb,p_created_by uuid default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_purchase public.supplier_purchases; v_allocation jsonb; v_record public.financial_records; v_requested numeric(14,2); v_existing numeric(14,2); v_expense_existing numeric(14,2); v_remaining_purchase numeric(14,2); v_count integer := 0; begin if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' or jsonb_array_length(p_allocations)=0 then raise exception 'Debes indicar al menos una asignación'; end if; select * into v_purchase from public.supplier_purchases where id=p_purchase_id and company_id=p_company_id and is_deleted=false for update; if not found then raise exception 'La compra indicada no existe o no pertenece a la empresa'; end if; select coalesce(sum(amount),0) into v_existing from public.supplier_purchase_allocations where purchase_id=p_purchase_id; for v_allocation in select * from jsonb_array_elements(p_allocations) loop if nullif(v_allocation->>'financial_record_id','') is null then raise exception 'Cada asignación requiere un gasto de destino'; end if; v_requested:=round(coalesce((v_allocation->>'amount')::numeric,0),2); if v_requested<=0 then raise exception 'El importe de cada asignación debe ser mayor que cero'; end if; select * into v_record from public.financial_records where id=(v_allocation->>'financial_record_id')::uuid and company_id=p_company_id and type='expense' and is_deleted=false and vehicle_id is not null for update; if not found then raise exception 'El gasto seleccionado no existe, no pertenece a la empresa o no está asociado a un vehículo'; end if; select coalesce(sum(amount),0) into v_expense_existing from public.supplier_purchase_allocations where financial_record_id=v_record.id; if v_expense_existing+v_requested>v_record.amount+0.01 then raise exception 'La asignación de % excede el importe disponible del gasto %',v_requested,v_record.amount; end if; if exists(select 1 from public.supplier_purchase_allocations where purchase_id=p_purchase_id and financial_record_id=v_record.id) then raise exception 'El gasto ya está asignado a esta compra. Edita la asignación existente en lugar de duplicarla'; end if; insert into public.supplier_purchase_allocations(company_id,purchase_id,financial_record_id,amount,notes,created_by) values(p_company_id,p_purchase_id,v_record.id,v_requested,nullif(trim(v_allocation->>'notes'),''),p_created_by); v_existing:=v_existing+v_requested; v_count:=v_count+1; end loop; if v_existing>v_purchase.total+0.01 then raise exception 'La suma de asignaciones excede el total de la compra'; end if; v_remaining_purchase:=greatest(0,round(v_purchase.total-v_existing,2)); return jsonb_build_object('purchase_id',p_purchase_id,'allocations_added',v_count,'allocated_total',round(v_existing,2),'remaining',v_remaining_purchase); end; $$; revoke execute on function public.allocate_supplier_purchase(uuid,uuid,jsonb,uuid) from public,anon; grant execute on function public.allocate_supplier_purchase(uuid,uuid,jsonb,uuid) to authenticated;